import{_ as l,l as i,o as e,c as s,v as t,p as n,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"控制流图","description":"","frontmatter":{"title":"控制流图","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cfg-ir.md","filePath":"cs/cfg-ir.md","lastUpdated":1789023840000}'),h={name:"cs/cfg-ir.md"};function A(_,a,f,m,C,E){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="控制流图" tabindex="-1">控制流图 <a class="header-anchor" href="#控制流图" aria-label="Permalink to &quot;控制流图&quot;">​</a></h1><div class="epigraph"><p>基本块是单入口单出口的直线指令；块之间的跳转做成有向图，后课的数据流在这张图上迭代。</p><footer>—— 据 Allen, Control Flow Analysis, 1970；龙书第 8 章整理</footer></div><p>上一课<a href="/cs/ir-three-address">三地址中间表示</a>把 AST 压成指令序列，并点名基本块与 CFG，把 SSA 留给后课。本课不重写 \\(x\\leftarrow y\\,\\mathrm{op}\\,z\\)。缺口是把「块」钉死：领导者、后继、不可约环。同一变量仍可多次赋值；改名是下一课。图算法课的<a href="/cs/graph-definition">图</a>在这里第一次成为程序的控制图。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>直线序列里，跳转与跳转目标把流切开。领导者：第一条指令、跳转的目标、跳转的下一指令。块：从领导者到下一块之前的最长直线。边：块末的条件/无条件跳、落到后继领导者。缺口是这张图，不是再遍历 AST。</p><p>循环：回边指向支配者（支配下一课才形式化，本课先认「跳到更早的块」）。不可约 CFG：多入口环，不能只靠自然循环的单一头。分析仍可做，只是循环优化要小心。本课承认不可约，不强制先把程序变成可约。</p><h3 id="块不是源里的「一段复合语句」" tabindex="-1">块不是源里的「一段复合语句」 <a class="header-anchor" href="#块不是源里的「一段复合语句」" aria-label="Permalink to &quot;块不是源里的「一段复合语句」&quot;">​</a></h3><p>源的 <code>{}</code> 与块不对齐：短路、<code>&amp;&amp;</code> 会拆块；<code>goto</code> 会并块。CFG 以 IR 为准。异常边（可能抛）是更后的异常表；本课先忽略，或点名为额外后继。</p><p><span class="marginnote">Allen 1970 控制流分析。龙书第 8 章基本块与流图。Appel 的 canon 把树变成块。本课要领导者算法，不插 φ。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>扫指令标领导者，切块，按跳转填后继/前驱。过程调用可作为块内操作或拆成调用块，约定一种。不可达块可删。输出：块链表 + 后继数组。</p>',11)),(e(),n(c,null,{default:r(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIN%5B%22%E4%B8%89%E5%9C%B0%E5%9D%80%E5%BA%8F%E5%88%97%22%5D%20--%3E%20LEAD%5B%22%E9%A2%86%E5%AF%BC%E8%80%85%22%5D%0A%20%20LEAD%20--%3E%20BLK%5B%22%E5%9F%BA%E6%9C%AC%E5%9D%97%22%5D%0A%20%20BLK%20--%3E%20CFG%5B%22CFG%22%5D%0A%20%20CFG%20--%3E%20SSA%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ASSA%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><a href="/cs/topo-sort">拓扑</a> 在无环片段上给线性序；有回边则数据流必须迭代，不能只拓扑一次。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课到达定值、活跃、支配都吃 CFG。正确性：块内顺序固定，优化不得把有副作用的指令跨过可能不执行的跳转。关键边（后继有多个前驱）在插代码时要先拆，本课点名。</p><p>不要把调用图与 CFG 混：调用图的节点是过程，CFG 的节点是块。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 SSA、不算支配、不选指令。不把解释器 PC 当 CFG。后课默认：中端对象是 CFG 上的三地址。静态单赋值在下一课用 φ 处理汇合。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>领导者切基本块；跳转成 CFG 边。</li><li>不可约环允许存在；数据流靠迭代。</li><li>多次赋值仍合法；SSA 是下一课约束。</li><li>出处：Allen, 1970；Aho et al., 龙书第 8 章。</li></ul>',8))])}const F=l(h,[["render",A]]);export{S as __pageData,F as default};
